/// <summary>
/// The <c>AVAWorkFullModeIDisposable</c> represents a iDisposable interface for work Locked process.
/// </summary>
/// <remarks>
/// AVA_6726_8001_RFFull_WorkLockMode
/// </remarks>
class AVAWorkFullModeIDisposable implements System.IDisposable
{
    public AVAWorkFullLockMode  workFullLockMode;
    public boolean              finishedSplit;

    static AVAWorkFullModeIDisposable instance;

}

