protected void new()
{
    if (!AVAWorkFullModeIDisposable::current())
    {
        instance = this;
    }
    else
    {
        instance = AVAWorkFullModeIDisposable::current();
    }
}

/// <summary>
/// AVA_6726_8001_RFFull_WorkLockMode
/// </summary>
/// <returns>
/// Current instance of <c>AVAWorkFullModeIDisposable</c>
/// </returns>
/// <remarks>
/// AVA_6726_8001_RFFull_WorkLockMode
/// </remarks>
public static AVAWorkFullModeIDisposable current()
{
    return instance;
}

public static AVAWorkFullModeIDisposable construct()
{
    return new AVAWorkFullModeIDisposable();
}
